CSQ_EXPECTED_PRIORITISED_CONSEQUENCE = [
    'upstream_gene_variant',
    'start_lost&NMD_transcript_variant',
    'stop_gained&frameshift_variant',
    'splice_acceptor_variant&non_coding_transcript_variant',
    'intron_variant&NMD_transcript_variant'
]


def test_vep_ranking():
    """
    Test VEP effect ranking reduction method.
    """
    # GIVEN a variant with VEP results
    # WHEN prioritising
    for expected_consequence, csq_data in zip(CSQ_EXPECTED_PRIORITISED_CONSEQUENCE, CSQ_DATA):
        most_significant_entry = rank_vep_predictions(vep_csq_keys=CSQ_FIELDS,
                                                      csq_data=csq_data)
        # THEN expect the the worst effect to be prioritised
        assert most_significant_entry.Consequence == expected_consequence


def test_vep_bad_data_format():
    """
    Test for raising error on malformed input
    """
    # GIVEN a variant with malformed VEP results
    # WHEN prioritising
    # THEN expect ValueError
    with pytest.raises(ValueError):
        rank_vep_predictions(vep_csq_keys=['Allele', 'Consequence'],
                             csq_data='C|intron_variant|HIGH')

    with pytest.raises(ValueError):
        rank_vep_predictions(vep_csq_keys=['Allele', 'Consequence', 'Impact'],
                             csq_data='C|intron_variant')

    with pytest.raises(ValueError):
        rank_vep_predictions(vep_csq_keys=['Allele', 'Consequence', 'Impact'],
                             csq_data='')

    with pytest.raises(ValueError):
        rank_vep_predictions(vep_csq_keys=[],
                             csq_data='C|intron_variant|HIGH')


def test_invalid_so_term():
    """
    Test for checking an error is raised when supplying an invalid SO term
    """
    # GIVEN a variant with undefined SO term
    # WHEN prioritising
    # THEN expect KeyError since SO term is invalid
    with pytest.raises(KeyError):
        rank_vep_predictions(vep_csq_keys=['Allele', 'Consequence'],
                             csq_data='C|not_a_so_term')
